content.query:
let incidentStart={TimeRange:start};
let incidentEnd={TimeRange:end};
let filterId=trim(' ','{JobIdFilter}');
customEvents
| where timestamp between (incidentStart .. incidentEnd)
| where name in ('BatchTaskStart','BatchTaskFinished','BatchTaskFailure')
| extend BatchJobId=tostring(customDimensions['BatchJobId'])
| where isempty(filterId) or BatchJobId == filterId
| summarize Starts=countif(name=='BatchTaskStart'), Finishes=countif(name=='BatchTaskFinished'), Failures=countif(name=='BatchTaskFailure') by TimeUtc=bin(timestamp,5m)
| order by TimeUtc asc
